{
  "id": "voyager.before-after",
  "version": 1,
  "title": "Compare versions",
  "description": "Inspect two image versions with a keyboard-operable comparison slider.",
  "tags": ["media", "comparison", "review"],
  "renderer": "spec",
  "entrypoint": "spec.json",
  "inputSchema": {
    "type": "object",
    "properties": {
      "beforeRef": {
        "type": "string"
      },
      "afterRef": {
        "type": "string"
      },
      "beforeLabel": {
        "type": "string"
      },
      "afterLabel": {
        "type": "string"
      }
    },
    "required": [],
    "additionalProperties": false
  },
  "actions": [
    {
      "id": "comparison_notes",
      "label": "Send comparison notes",
      "inputSchema": {
        "type": "object",
        "properties": {
          "notes": {
            "type": "string"
          }
        },
        "required": ["notes"],
        "additionalProperties": false
      },
      "delivery": {
        "kind": "agent"
      },
      "cardinality": "repeatable"
    }
  ],
  "bindings": [],
  "exampleInputs": {
    "beforeLabel": "Original",
    "afterLabel": "Revised"
  },
  "fallback": "Inspect two image versions with a keyboard-operable comparison slider. You can also provide your choices in the conversation."
}

{
